'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session=null,store={companies:[],contacts:[],contact_emails:[],notes:[],followups:[],activities:[],images:[]},searchTerm='',directoryView='contacts',showArchived=false,reminderScope='Tous';
const dialog=document.querySelector('#detail');
const initials=name=>name.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();
const isAdmin=()=>session?.organization.role==='admin';
const memberName=id=>session?.members.find(m=>m.id===id)?.name||'Non attribué';
const companyBy=id=>store.companies.find(c=>c.id===id);
const contactBy=id=>store.contacts.find(c=>c.id===id);
const addressFor=id=>store.contact_emails.filter(e=>e.contact_id===id).map(e=>e.email);
const localDate=v=>new Intl.DateTimeFormat('fr-TN',{timeZone:'Africa/Tunis',dateStyle:'medium',timeStyle:'short',hourCycle:'h23'}).format(new Date(v));
const dayKey=v=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Tunis',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));
const today=()=>dayKey(new Date());
const pending=()=>store.followups.filter(f=>f.status==='pending');
function errorText(message){return `<p class="connection-error" role="alert">${esc(message)}</p>`;}
async function api(path,options={}){const response=await fetch('/api/v1'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(session?{'X-CSRF-Token':session.csrfToken}:{}),...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});if(response.status===204)return null;const data=await response.json();if(!response.ok){if(response.status===401&&location.pathname!=='/connexion'){session=null;go('/connexion');}throw Error(data.message||'La requête a échoué.');}return data;}
async function load(){[session,store]=await Promise.all([api('/me'),api('/state')]);}
async function sync(){await load();render();}
function go(path){dialog.close();history.pushState({},'',path);searchTerm='';render();window.scrollTo(0,0);}
function safeAction(fn){return async()=>{try{await fn();}catch(e){toast(e.message);}};}
function bindForm(id,handler){const f=document.getElementById(id);f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button[type="submit"]');if(b.disabled)return;const data=Object.fromEntries(new FormData(f));b.disabled=true;let errors=f.querySelector('[role="alert"]');if(errors)errors.remove();try{await handler(data,f);}catch(err){f.insertAdjacentHTML('beforeend',errorText(err.message));}finally{b.disabled=false;}};}
function modal(title,body,drawer=false){dialog.classList.toggle('contact-drawer',drawer);showDetail(esc(title),body);}
function links(){return [['grid','Tableau de bord','/app'],['people','Entreprises & contacts','/app/contacts'],['clock','Relances','/app/relances']];}
function shell(content){const path=location.pathname;const user=session.user;app.innerHTML=`<div class="workspace ${path==='/app'?'reference-dashboard':''}"><aside class="sidebar">${brand}<div class="workspace-label">VOTRE ESPACE</div><button class="workspace-switch" id="switch-org"><span class="workspace-icon">${esc(initials(session.organization.name))}</span><span><strong>${esc(session.organization.name)}</strong><small>Espace privé partagé</small></span><span>⌄</span></button><nav aria-label="Navigation de l’espace">${links().map(([i,n,p])=>`<a href="${p}" class="nav-item ${path===p?'selected':''}" ${path===p?'aria-current="page"':''}>${icon(i)} ${n}</a>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-item" id="members-button">${icon('people')} Membres et accès</button><a class="nav-item" href="/">${icon('arrow')} Accueil public</a><div class="profile"><span class="avatar dark">${esc(initials(user.name))}</span><div><strong>${esc(user.name)}</strong><small>${isAdmin()?'Administrateur':'Collaborateur'}</small></div><button id="signout" aria-label="Se déconnecter" title="Se déconnecter">↗</button></div></div></aside><div class="workspace-main"><header class="dashboard-top"><div class="global-search"><label class="search-box">${icon('search')}<input id="global-search" type="search" placeholder="Rechercher une entreprise, un contact…" aria-label="Recherche globale"></label><div id="global-results" class="global-results" hidden></div></div><div class="top-actions"><button class="button small" id="global-add">＋ Ajouter</button><span class="avatar dark">${esc(initials(user.name))}</span></div></header><main class="dashboard-content">${content}<footer class="dashboard-footer"><span>Ciblix · ${esc(session.organization.name)}</span><span>Données enregistrées · Gmail non connecté</span></footer></main></div></div>`;document.querySelector('#signout').onclick=safeAction(async()=>{await api('/auth/logout',{method:'POST'});session=null;store={};go('/connexion');});document.querySelector('#switch-org').onclick=switchOrg;document.querySelector('#members-button').onclick=safeAction(membersModal);document.querySelector('#global-add').onclick=()=>modal('Ajouter à votre espace',`<div class="board-dialog-actions"><button class="button" id="new-company">${icon('building')} Une entreprise</button><button class="button board-secondary" id="new-contact">${icon('people')} Un contact</button><button class="button board-secondary" id="new-followup">${icon('clock')} Une relance</button></div>`);document.querySelector('#global-add').addEventListener('click',()=>{document.querySelector('#new-company').onclick=()=>entityForm('companies');document.querySelector('#new-contact').onclick=()=>entityForm('contacts');document.querySelector('#new-followup').onclick=()=>followupForm();});document.querySelector('#global-search').oninput=e=>{const q=e.target.value.toLocaleLowerCase('fr').trim(),results=document.querySelector('#global-results');results.hidden=!q;if(!q)return;const list=[...store.companies.filter(c=>!c.archived_at&&c.name.toLocaleLowerCase('fr').includes(q)).map(c=>({...c,type:'Entreprise'})),...store.contacts.filter(c=>!c.archived_at&&(c.name+' '+addressFor(c.id)).toLocaleLowerCase('fr').includes(q)).map(c=>({...c,type:'Contact'}))].slice(0,8);results.innerHTML=list.map((r,i)=>`<button data-search-result="${i}"><span>${r.type}</span><strong>${esc(r.name)}</strong>${icon('arrow')}</button>`).join('')||'<p>Aucun résultat.</p>';results.querySelectorAll('[data-search-result]').forEach(b=>b.onclick=()=>{const r=list[Number(b.dataset.searchResult)];results.hidden=true;r.type==='Entreprise'?go('/app/entreprises/'+r.id):contactDrawer(r.id);});};}
function greeting(title,description,action){return `<div class="greeting page-greeting"><div><span class="eyebrow">VOTRE ESPACE PARTAGÉ</span><h1>${esc(title)}<span>.</span></h1><p>${esc(description)}</p></div>${action?`<button class="button" id="page-add">＋ ${esc(action)}</button>`:''}</div>`;}
function boardHeading(title,url,label='Voir toutes'){return `<div class="board-panel-heading"><h2>${title}</h2><a href="${url}">${label} ${icon('arrow')}</a></div>`;}
function reminderRow(r){const person=contactBy(r.contact_id),company=companyBy(r.company_id);return `<article class="board-reminder"><button class="board-person" data-open-contact="${person?.id||''}"><span class="avatar">${esc(initials(person?.name||company?.name||'R'))}</span><span><strong>${esc(company?.name||'Sans entreprise')}</strong><small>${esc(person?.name||'Sans contact')}</small></span></button><time>${esc(new Intl.DateTimeFormat('fr-TN',{timeZone:'Africa/Tunis',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(r.due_at)))}</time><div class="board-reminder-context"><p>${esc(r.subject)}</p><span>${esc(memberName(r.owner_user_id))}</span></div><button class="icon-button" data-draft="${r.id}" aria-label="Préparer un brouillon local">${icon('mail')}</button><button class="icon-button" data-followup-actions="${r.id}" aria-label="Actions sur la relance">···</button></article>`;}
function activityRows(){return store.activities.slice(0,5).map(a=>`<div class="board-activity-row"><span class="timeline-dot"></span><span class="avatar">${esc(initials(a.actor_name))}</span><div><p><strong>${esc(a.actor_name)}</strong> · ${esc(a.summary)}</p><small>${esc(localDate(a.created_at))}</small></div></div>`).join('')||'<p class="empty">Les actions de votre équipe apparaîtront ici.</p>';}
let evolutionMonths=12;
const chartColors=['#14532D','#166534','#3f7453','#476b57','#5f7267'];
function contactEvolution(){const now=new Date();const months=Array.from({length:evolutionMonths},(_,i)=>new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()-evolutionMonths+1+i,1)));const counts=months.map(m=>{const next=new Date(Date.UTC(m.getUTCFullYear(),m.getUTCMonth()+1,1));return store.contacts.filter(c=>new Date(c.created_at)<next&&!c.archived_at).length;});const max=Math.max(5,...counts);return `<div class="contact-evolution" role="img" aria-label="Évolution des contacts : ${months.map((m,i)=>m.toLocaleDateString('fr-TN',{month:'long',timeZone:'UTC'})+' '+counts[i]).join(', ')}"><div class="evolution-axis">${Array.from({length:6},(_,i)=>`<span>${Math.round(max*(5-i)/5)}</span>`).join('')}</div><div class="evolution-bars">${months.map((m,i)=>`<div class="evolution-bar"><svg viewBox="0 0 24 160" preserveAspectRatio="none" aria-hidden="true"><rect x="2" y="${160-counts[i]/max*160}" width="20" height="${counts[i]/max*160}" rx="3" fill="#14532D"/></svg><span>${m.toLocaleDateString('fr-TN',{month:'short',timeZone:'UTC'}).replace('.','')}</span></div>`).join('')}</div></div>`;}
function contactOrigins(){const counts=new Map();for(const c of store.contacts.filter(c=>!c.archived_at))counts.set(c.source||'Non renseignée',(counts.get(c.source||'Non renseignée')||0)+1);const total=[...counts.values()].reduce((a,b)=>a+b,0);const groups=[...counts].sort((a,b)=>b[1]-a[1]);let offset=0;return `<div class="origins-chart"><div class="donut-figure"><svg viewBox="0 0 150 150" class="origin-donut" role="img" aria-label="Origine des ${total} contacts"><circle cx="75" cy="75" r="56" fill="none" stroke="#edf1ef" stroke-width="18"/>${groups.map(([name,value],i)=>{const length=value/(total||1)*351.858;const part=`<circle cx="75" cy="75" r="56" fill="none" stroke="${chartColors[i%chartColors.length]}" stroke-width="18" stroke-dasharray="${length} ${351.858-length}" stroke-dashoffset="${-offset}" transform="rotate(-90 75 75)"><title>${esc(name)} : ${value}</title></circle>`;offset+=length;return part;}).join('')}</svg><div class="donut-center" aria-hidden="true"><strong>${total}</strong><span>contacts</span></div></div><div class="origin-legend">${groups.map(([n,v],i)=>`<div><svg viewBox="0 0 10 10" aria-hidden="true"><circle cx="5" cy="5" r="5" fill="${chartColors[i%chartColors.length]}"/></svg><span>${esc(n)}</span><strong>${Math.round(v/(total||1)*100)}%</strong></div>`).join('')||'<p>Les origines apparaîtront après vos premiers ajouts.</p>'}</div></div>`;}
function sectorChart(){const counts=new Map();for(const c of store.contacts.filter(c=>!c.archived_at)){const sector=companyBy(c.company_id)?.sector||'Non renseigné';counts.set(sector,(counts.get(sector)||0)+1);}const total=[...counts.values()].reduce((a,b)=>a+b,0);return `<div class="sector-chart">${[...counts].sort((a,b)=>b[1]-a[1]).slice(0,6).map(([n,v],i)=>{const pct=Math.round(v/(total||1)*100);return `<div><span>${esc(n)}</span><svg viewBox="0 0 130 13" aria-hidden="true"><rect width="130" height="13" rx="6" fill="#eef3f0"/><rect width="${130*pct/100}" height="13" rx="6" fill="${['#14532D','#166534','#3f7453','#476b57','#5f7267','#475569'][i]}"/></svg><strong>${pct}%</strong></div>`;}).join('')||'<p class="empty">Les secteurs des entreprises associées à vos contacts apparaîtront ici.</p>'}</div>`;}
function dashboardLive(){document.title='Tableau de bord — Ciblix';const activeContacts=store.contacts.filter(c=>!c.archived_at),activeCompanies=store.companies.filter(c=>!c.archived_at);const due=pending().filter(r=>dayKey(r.due_at)===today()),late=pending().filter(r=>dayKey(r.due_at)<today());const thisMonth=new Date().toISOString().slice(0,7);shell(`<div class="board-welcome"><div><h1>Bonjour ${esc(session.user.name.split(' ')[0])}</h1><p>Voici l’essentiel de votre activité aujourd’hui.</p></div><time>${icon('clock')} ${esc(new Intl.DateTimeFormat('fr-TN',{timeZone:'Africa/Tunis',dateStyle:'full'}).format(new Date()))}</time></div><section class="board-metrics image-metrics" aria-label="Votre activité en un regard">${[['people','Entreprises',activeCompanies.length,'↑ +'+activeCompanies.filter(c=>c.created_at.slice(0,7)===thisMonth).length+' ce mois','/app/contacts?vue=entreprises'],['people','Contacts',activeContacts.length,'↑ +'+activeContacts.filter(c=>c.created_at.slice(0,7)===thisMonth).length+' ce mois','/app/contacts'],['clock','Relances prévues',pending().length,late.length?'dont '+late.length+' en retard':'Aucune relance en retard','/app/relances'],['mail','E-mails reçus','—','Gmail non connecté','#dashboard-emails']].map(([i,n,v,s,url],index)=>`<a class="board-metric image-metric-${index}" href="${url}"><span class="metric-icon">${icon(i)}</span><div><span>${n}</span><strong>${v}</strong><small class="${index===2&&late.length?'is-overdue':''}">${s}</small></div></a>`).join('')}</section><section class="dashboard-analytics" id="dashboard-stats" aria-label="Analyse des contacts"><article class="panel analytics-evolution"><div class="analytics-heading"><h2>Évolution des contacts</h2><label><span class="sr-only">Période du graphique</span><select id="evolution-period"><option value="12" ${evolutionMonths===12?'selected':''}>12 derniers mois</option><option value="6" ${evolutionMonths===6?'selected':''}>6 derniers mois</option></select></label></div><div class="evolution-count">${activeContacts.length} contacts</div>${contactEvolution()}</article><article class="panel analytics-origins"><div class="analytics-heading"><h2>Origine des contacts</h2></div>${contactOrigins()}</article><article class="panel analytics-sectors"><div class="analytics-heading"><h2>Répartition par secteur</h2></div>${sectorChart()}</article></section><div class="board-main-grid image-lower-grid"><section class="panel board-panel" id="dashboard-tasks">${boardHeading('Relances du jour <span class="today-count">'+due.length+'</span>','/app/relances')}${due.length?due.map(reminderRow).join(''):'<div class="board-empty">'+icon('check')+'<h3>Votre journée est à jour.</h3><p>Planifiez une prochaine attention pour garder le lien.</p><button class="text-link" id="empty-followup">Planifier une relance '+icon('arrow')+'</button></div>'}${late.length?`<a href="/app/relances" class="board-sync-note is-overdue">${icon('bell')} ${late.length} relance(s) en retard à consulter dans l’agenda.</a>`:''}</section><section class="panel board-panel" id="dashboard-emails"><div class="board-panel-heading"><h2>Derniers e-mails reçus</h2><span class="tag">Gmail non connecté</span></div><div class="board-empty">${icon('mail')}<h3>Vos échanges, bientôt ici.</h3><p>La connexion Gmail sera ajoutée séparément. Aucun e-mail fictif n’est présenté comme reçu.</p></div></section></div>`);bindRecords();document.querySelector('#empty-followup')?.addEventListener('click',()=>followupForm());document.querySelector('#evolution-period').onchange=e=>{evolutionMonths=Number(e.target.value);dashboardLive();};const workspace=document.querySelector('.workspace');workspace.classList.add('image-dashboard');document.querySelector('.sidebar nav').innerHTML=[['grid','Tableau de bord','/app'],['building','Entreprises','/app/contacts?vue=entreprises'],['people','Contacts','/app/contacts'],['bell','Relances','/app/relances'],['mail','E-mails','#dashboard-emails'],['check','À faire','#dashboard-tasks'],['grid','Statistiques','#dashboard-stats']].map(([i,n,url])=>`<a href="${url}" class="nav-item ${url==='/app'?'selected':''}">${icon(i)} ${n}${n==='Relances'&&pending().length?'<span class="image-nav-badge">'+pending().length+'</span>':''}</a>`).join('');const user=session.user;document.querySelector('.top-actions').insertAdjacentHTML('beforeend',`<button id="dashboard-profile" class="dashboard-user"><strong>${esc(user.name)}</strong><small>${esc(session.organization.name)}</small></button>`);document.querySelector('#dashboard-profile').onclick=switchOrg;document.querySelector('.top-actions>.avatar').insertAdjacentHTML('beforebegin',`<button class="dashboard-notifications icon-button" id="dashboard-notifications" aria-label="Notifications">${icon('bell')}${late.length?'<i></i>':''}</button>`);document.querySelector('#dashboard-notifications').onclick=()=>modal('Votre suivi',`<p>${due.length} relance(s) aujourd’hui, ${late.length} en retard.</p><p>Gmail n’est pas encore connecté.</p>`);document.querySelector('#members-button').innerHTML=icon('settings')+' Paramètres';}

const directoryState={owner:'',sector:'',status:'',page:1,pageSize:10,sort:'name',direction:1};
function followupsFor(c,type){return pending().filter(r=>type==='companies'?r.company_id===c.id:r.contact_id===c.id).sort((a,b)=>new Date(a.due_at)-new Date(b.due_at));}
function tracking(c,type){if(c.archived_at)return {key:'archived',label:'Archivé'};const next=followupsFor(c,type);if(next.some(r=>dayKey(r.due_at)<today()))return {key:'late',label:'En retard'};if(next.length)return {key:'planned',label:'Relance prévue'};const related=store.followups.filter(r=>type==='companies'?r.company_id===c.id:r.contact_id===c.id);if(related.length&&related.every(r=>r.status==='completed'||r.status==='cancelled'))return {key:'done',label:'Suivi terminé'};return {key:'none',label:'À organiser'};}
function directoryPeople(c,type){return type==='companies'?store.contacts.filter(p=>p.company_id===c.id&&!p.archived_at):[];}
function directorySector(c,type){return type==='companies'?c.sector:companyBy(c.company_id)?.sector||'';}
function directory(){document.title='Entreprises & contacts — Ciblix';directoryView=new URLSearchParams(location.search).get('vue')==='entreprises'?'companies':'contacts';const company=directoryView==='companies';const sectors=[...new Set(store[directoryView].map(c=>directorySector(c,directoryView)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr'));shell(`<div class="directory-heading"><div><span class="eyebrow">VOTRE RÉSEAU PARTAGÉ</span><h1>Entreprises & contacts<span>.</span></h1><p>Le contexte, les bonnes personnes et la prochaine attention.</p></div><button class="button" id="page-add">＋ ${company?'Ajouter une entreprise':'Ajouter un contact'}</button></div><section class="directory-surface"><div class="directory-switcher"><div class="entity-tabs" role="group" aria-label="Vue du répertoire"><button data-directory="companies" class="${company?'active':''}" aria-pressed="${company}">${icon('building')} Entreprises <span>${store.companies.filter(c=>!c.archived_at).length}</span></button><button data-directory="contacts" class="${!company?'active':''}" aria-pressed="${!company}">${icon('people')} Contacts <span>${store.contacts.filter(c=>!c.archived_at).length}</span></button></div><div class="directory-tools"><button class="text-link" id="export">Exporter les contacts ${icon('arrow')}</button>${!company?`<label class="card-photo-button">${icon('phone')} Carte de visite<input id="photo-card" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"></label>`:''}</div></div><div class="directory-filter-bar"><label class="search-box">${icon('search')}<input id="directory-search" type="search" value="${esc(searchTerm)}" placeholder="Nom, entreprise, e-mail, téléphone…" aria-label="Rechercher dans le répertoire"></label><button class="directory-filter-toggle" id="toggle-directory-filters" aria-expanded="false">Filtres</button><label class="filter-select"><span>Responsable</span><select id="filter-owner"><option value="">Tous les responsables</option>${session.members.map(m=>`<option value="${m.id}" ${directoryState.owner===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}<option value="unassigned" ${directoryState.owner==='unassigned'?'selected':''}>Non attribué</option></select></label><label class="filter-select"><span>Secteur</span><select id="filter-sector"><option value="">Tous les secteurs</option>${sectors.map(s=>`<option ${directoryState.sector===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label class="filter-select"><span>Suivi</span><select id="filter-status"><option value="">Tous les statuts</option>${[['late','En retard'],['planned','Relance prévue'],['none','À organiser'],['done','Suivi terminé'],['archived','Archivé']].map(([v,n])=>`<option value="${v}" ${directoryState.status===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="directory-list-meta"><p id="result-count" aria-live="polite"></p><div><label><input id="show-archived" type="checkbox" ${showArchived?'checked':''}> Inclure les archives</label><button id="reset-directory" class="text-link">Réinitialiser</button></div></div><div class="directory-mobile-sort"><label>Trier par<select id="mobile-sort"><option value="name">Nom</option><option value="relation">Entreprise / interlocuteur</option><option value="owner">Responsable</option><option value="last">Dernier échange</option><option value="next">Prochaine relance</option><option value="status">Statut du suivi</option></select></label><label>Ordre<select id="mobile-sort-direction"><option value="1">Croissant</option><option value="-1">Décroissant</option></select></label></div><div id="directory-results"></div><div id="directory-pagination" class="directory-pagination"></div></section><p class="directory-gmail-note">${icon('shield')} Données partagées dans ${esc(session.organization.name)}. Les échanges Gmail ne sont pas encore connectés.</p>`);document.querySelector('#page-add').onclick=()=>entityForm(directoryView);document.querySelectorAll('[data-directory]').forEach(b=>b.onclick=()=>{directoryState.page=1;directoryState.sector='';go('/app/contacts'+(b.dataset.directory==='companies'?'?vue=entreprises':''));});document.querySelector('#directory-search').oninput=e=>{searchTerm=e.target.value;directoryState.page=1;directoryResults();};for(const key of ['owner','sector','status'])document.querySelector('#filter-'+key).onchange=e=>{directoryState[key]=e.target.value;directoryState.page=1;directoryResults();};document.querySelector('#show-archived').onchange=e=>{showArchived=e.target.checked;directoryState.page=1;directoryResults();};document.querySelector('#reset-directory').onclick=resetDirectory;document.querySelector('#toggle-directory-filters').onclick=e=>{const expanded=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',String(expanded));document.querySelector('.directory-filter-bar').classList.toggle('filters-expanded',expanded);};document.querySelector('#export').onclick=exportContacts;document.querySelector('#mobile-sort').onchange=e=>{directoryState.sort=e.target.value;directoryState.page=1;directoryResults();};document.querySelector('#mobile-sort-direction').onchange=e=>{directoryState.direction=Number(e.target.value);directoryState.page=1;directoryResults();};document.querySelector('#photo-card')?.addEventListener('change',e=>{if(e.target.files[0])entityForm('contacts',null,e.target.files[0]);});directoryResults();}
function resetDirectory(){Object.assign(directoryState,{owner:'',sector:'',status:'',page:1,sort:'name',direction:1});showArchived=false;searchTerm='';directory();}
function directoryResults(){const type=directoryView,company=type==='companies',state=directoryState;const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr');const values=c=>{const people=directoryPeople(c,type),next=followupsFor(c,type)[0];return {name:c.name,relation:company?people[0]?.name||'':companyBy(c.company_id)?.name||'',owner:memberName(c.owner_user_id),last:null,next:next?new Date(next.due_at).getTime():null,status:tracking(c,type).label};};let list=store[type].filter(c=>{const people=directoryPeople(c,type);const hay=[c.name,c.sector,c.city,c.phone,c.job_title,companyBy(c.company_id)?.name,...addressFor(c.id),...people.flatMap(p=>[p.name,p.phone,...addressFor(p.id)])].join(' ');return ((!c.archived_at||showArchived||state.status==='archived')&&norm(hay).includes(norm(searchTerm))&&(!state.owner||(state.owner==='unassigned'?!c.owner_user_id:c.owner_user_id===state.owner))&&(!state.sector||directorySector(c,type)===state.sector)&&(!state.status||tracking(c,type).key===state.status));});list.sort((a,b)=>{const av=values(a)[state.sort],bv=values(b)[state.sort];if(av===null&&bv!==null)return 1;if(bv===null&&av!==null)return -1;const cmp=typeof av==='number'?av-bv:String(av??'').localeCompare(String(bv??''),'fr',{sensitivity:'base',numeric:true});return cmp*state.direction||a.id.localeCompare(b.id);});document.querySelector('#mobile-sort').value=state.sort;document.querySelector('#mobile-sort-direction').value=String(state.direction);const total=list.length,pages=Math.max(1,Math.ceil(total/state.pageSize));state.page=Math.min(state.page,pages);const start=(state.page-1)*state.pageSize,items=list.slice(start,start+state.pageSize);document.querySelector('#result-count').textContent=`${total} ${company?'entreprise'+(total>1?'s':''):'contact'+(total>1?'s':'')}${searchTerm||state.owner||state.sector||state.status?' correspondant aux filtres':''}`;
const columns=[['name',company?'Entreprise':'Contact'],['relation',company?'Interlocuteur principal':'Entreprise'],['owner','Responsable'],['last','Dernier échange'],['next','Prochaine relance'],['status','Suivi']];document.querySelector('#directory-results').innerHTML=total?`<table class="directory-table"><caption class="sr-only">${company?'Entreprises':'Contacts'} de votre organisation. Chaque ligne ouvre la fiche.</caption><thead><tr>${columns.map(([key,title])=>`<th scope="col" aria-sort="${state.sort===key?(state.direction===1?'ascending':'descending'):'none'}"><button data-sort="${key}">${title}<span aria-hidden="true">${state.sort===key?(state.direction===1?'↑':'↓'):'↕'}</span></button></th>`).join('')}<th scope="col"><span class="sr-only">Actions</span></th></tr></thead><tbody>${items.map(c=>{const people=directoryPeople(c,type),next=followupsFor(c,type)[0],status=tracking(c,type);return `<tr data-directory-row="${c.id}" tabindex="0" aria-label="Ouvrir la fiche de ${esc(c.name)}" class="${c.archived_at?'archived-row':''}"><td data-label="${company?'Entreprise':'Contact'}"><div class="table-identity"><span class="${company?'company-avatar':'avatar'}">${esc(initials(c.name))}</span><span><a href="${company?'/app/entreprises/'+c.id:'#'}" ${!company?`data-open-directory-contact="${c.id}"`:''}>${esc(c.name)}</a><small>${esc(company?(c.sector||'Secteur non renseigné')+(c.city?' · '+c.city:''):addressFor(c.id)[0]||c.phone||c.job_title||'Coordonnées à compléter')}</small></span></div></td><td data-label="${company?'Interlocuteur':'Entreprise'}"><strong class="table-secondary">${esc(company?people[0]?.name||'Aucun contact':companyBy(c.company_id)?.name||'Sans entreprise')}</strong><small>${company?(people.length>1?'+ '+(people.length-1)+' autre(s) contact(s)':esc(people[0]?.job_title||'')):esc(c.job_title||'')}</small></td><td data-label="Responsable"><span class="table-owner">${esc(memberName(c.owner_user_id))}</span></td><td data-label="Dernier échange"><span class="table-missing">Non disponible</span><small>Gmail non connecté</small></td><td data-label="Prochaine relance">${next?`<strong class="table-secondary">${esc(localDate(next.due_at))}</strong><small>${esc(next.subject)}</small>`:'<span class="table-missing">Aucune prévue</span>'}</td><td data-label="Suivi"><span class="tracking-badge tracking-${status.key}">${status.label}</span></td><td class="table-row-actions"><button class="icon-button" data-directory-actions="${c.id}" aria-label="Actions pour ${esc(c.name)}">···</button></td></tr>`;}).join('')}</tbody></table>`:`<div class="directory-empty">${icon(company?'building':'people')}<h2>${store[type].length?'Aucun résultat pour ces filtres.':'Votre réseau commence ici.'}</h2><p>${store[type].length?'Essayez un autre terme ou réinitialisez les filtres.':'Ajoutez votre première fiche pour retrouver ses coordonnées et son suivi.'}</p><button class="button small" id="directory-empty-action">${store[type].length?'Réinitialiser les filtres':company?'Ajouter une entreprise':'Ajouter un contact'}</button></div>`;
document.querySelector('#directory-empty-action')?.addEventListener('click',()=>store[type].length?resetDirectory():entityForm(type));document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{state.direction=state.sort===b.dataset.sort?-state.direction:1;state.sort=b.dataset.sort;state.page=1;directoryResults();});const open=id=>company?go('/app/entreprises/'+id):contactDrawer(id);document.querySelectorAll('[data-directory-row]').forEach(row=>{row.onclick=e=>{if(!e.target.closest('button,a,input,select'))open(row.dataset.directoryRow);};row.onkeydown=e=>{if(e.target===row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();open(row.dataset.directoryRow);}};});document.querySelectorAll('[data-open-directory-contact]').forEach(a=>a.onclick=e=>{e.preventDefault();contactDrawer(a.dataset.openDirectoryContact);});document.querySelectorAll('[data-directory-actions]').forEach(b=>b.onclick=()=>{const c=store[type].find(c=>c.id===b.dataset.directoryActions);modal(c.name,`<p>Gérez cette fiche partagée avec votre équipe.</p>${recordActions(c,type)}`);bindEntityActions(c,type);});document.querySelector('#directory-pagination').innerHTML=`<span>${total?start+1:0}–${Math.min(start+state.pageSize,total)} sur ${total}</span><label>Lignes par page <select id="page-size">${[10,25,50].map(n=>`<option ${n===state.pageSize?'selected':''}>${n}</option>`).join('')}</select></label><nav aria-label="Pagination du répertoire"><button id="previous-page" ${state.page===1?'disabled':''} aria-label="Page précédente">←</button><span>Page ${state.page} sur ${pages}</span><button id="next-page" ${state.page===pages?'disabled':''} aria-label="Page suivante">→</button></nav>`;document.querySelector('#page-size').onchange=e=>{state.pageSize=Number(e.target.value);state.page=1;directoryResults();};document.querySelector('#previous-page').onclick=()=>{state.page--;directoryResults();};document.querySelector('#next-page').onclick=()=>{state.page++;directoryResults();};}

function ownerOptions(selected){return session.members.filter(m=>m.active).map(m=>`<option value="${m.id}" ${selected===m.id?'selected':''}>${esc(m.name)}</option>`).join('');}
function entityForm(type,id=null,file=null){const company=type==='companies',c=id?store[type].find(c=>c.id===id):{};modal(id?'Modifier la fiche':company?'Une nouvelle entreprise':'Un nouveau contact',`<form id="entity-form" class="prototype-form">${file?'<div class="business-card-preview"><p>La photo sera jointe après création du contact. Renseignez les champs manuellement.</p></div>':''}<label>Nom${company?' de l’entreprise':' et prénom'}<input name="name" required maxlength="150" value="${esc(c.name)}"></label>${company?`<label>Secteur<input name="sector" maxlength="150" value="${esc(c.sector)}"></label><label>Ville<input name="city" maxlength="150" value="${esc(c.city)}"></label><label>À propos<textarea name="description" maxlength="5000">${esc(c.description)}</textarea></label>`:`<label>Entreprise<select name="company_id"><option value="">Sans entreprise</option>${store.companies.filter(x=>!x.archived_at).map(x=>`<option value="${x.id}" ${c.company_id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Fonction<input name="job_title" maxlength="150" value="${esc(c.job_title)}"></label><label>E-mails (un par ligne)<textarea name="email_list" rows="2" placeholder="contact@entreprise.tn">${esc(id?addressFor(id).join('\n'):'')}</textarea></label><label>Origine du contact<select name="source">${['Non renseignée','Recommandation','Salon / événement','Site web','Prospection','Autre'].map(s=>`<option ${c.source===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Téléphone<input name="phone" type="tel" maxlength="50" value="${esc(c.phone)}"></label>`}<label>Responsable<select name="owner_user_id">${ownerOptions(c.owner_user_id||session.user.id)}</select></label><button class="button" type="submit">Enregistrer ${icon('check')}</button></form>`);bindForm('entity-form',async d=>{if(!company){d.company_id=d.company_id||null;d.emails=d.email_list.split(/[\n;,]+/).map(v=>v.trim()).filter(Boolean);delete d.email_list;}const saved=await api('/'+type+(id?'/'+id:''),{method:id?'PATCH':'POST',body:d});let imageError;if(file){try{await uploadCard(saved.id,file);}catch(e){imageError=e.message;}}dialog.close();await load();render();if(company)go('/app/entreprises/'+saved.id);else contactDrawer(saved.id);toast(imageError?'Fiche enregistrée, photo non enregistrée : '+imageError:'Fiche enregistrée.');});}
async function uploadCard(id,file){if(file.size>8388608||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choisissez une image PNG, JPEG ou WebP de moins de 8 Mo.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('Lecture de la photo impossible.'));r.readAsDataURL(file);});await api('/contacts/'+id+'/card',{method:'POST',body:{mime_type:file.type,data}});}
function recordActions(c,type){return `<div class="record-action-bar"><button class="text-link" id="record-edit">Modifier</button><button class="text-link" id="record-archive">${c.archived_at?'Restaurer':'Archiver'}</button>${isAdmin()?'<button class="text-link" id="record-delete">Supprimer définitivement</button>':''}</div>`;}
function bindEntityActions(c,type){document.querySelector('#record-edit').onclick=()=>entityForm(type,c.id);document.querySelector('#record-archive').onclick=safeAction(async()=>{await api('/'+type+'/'+c.id,{method:'PATCH',body:{archived:!c.archived_at}});dialog.close();await sync();toast(c.archived_at?'Fiche restaurée.':'Fiche archivée.');});document.querySelector('#record-delete')?.addEventListener('click',()=>{modal('Confirmer la suppression',`<p>Supprimer définitivement « ${esc(c.name)} » ? ${type==='companies'?'Les contacts associés seront conservés sans entreprise.':''}</p><div class="board-dialog-actions"><button class="button" id="confirm-delete">Confirmer la suppression</button><button class="text-link" id="cancel-delete">Annuler</button></div>`);document.querySelector('#cancel-delete').onclick=()=>dialog.close();document.querySelector('#confirm-delete').onclick=safeAction(async()=>{await api('/'+type+'/'+c.id,{method:'DELETE'});dialog.close();await load();go('/app/contacts'+(type==='companies'?'?vue=entreprises':''));toast('Fiche supprimée.');});});}
function notesHTML(type,id){const notes=store.notes.filter(n=>n[type==='companies'?'company_id':'contact_id']===id);return `${notes.map(n=>`<article class="message-preview"><small>${esc(memberName(n.author_user_id))} · ${esc(localDate(n.created_at))}</small><p class="history-note">${esc(n.body)}</p><button class="text-link" data-note-edit="${n.id}">Modifier</button>${isAdmin()?` <button class="text-link" data-note-delete="${n.id}">Supprimer</button>`:''}</article>`).join('')||'<p class="empty">Ajoutez le contexte utile à votre équipe.</p>'}<form id="note-form" class="prototype-form"><label>Nouvelle note<textarea name="body" required maxlength="10000" rows="4"></textarea></label><button class="button small" type="submit">Ajouter la note</button></form>`;}
function bindNotes(type,id,refresh){bindForm('note-form',async d=>{await api('/notes',{method:'POST',body:{...d,[type==='companies'?'company_id':'contact_id']:id}});await load();refresh();toast('Note partagée enregistrée.');});document.querySelectorAll('[data-note-edit]').forEach(b=>b.onclick=()=>{const n=store.notes.find(n=>n.id===b.dataset.noteEdit);modal('Modifier la note',`<form id="edit-note" class="prototype-form"><label>Votre note<textarea name="body" required maxlength="10000" rows="6">${esc(n.body)}</textarea></label><button class="button" type="submit">Enregistrer</button></form>`);bindForm('edit-note',async d=>{await api('/notes/'+n.id,{method:'PATCH',body:d});dialog.close();await load();refresh();});});document.querySelectorAll('[data-note-delete]').forEach(b=>b.onclick=()=>{modal('Supprimer cette note ?',`<p>Cette suppression est définitive.</p><button class="button" id="confirm-note-delete">Confirmer la suppression</button>`);document.querySelector('#confirm-note-delete').onclick=safeAction(async()=>{await api('/notes/'+b.dataset.noteDelete,{method:'DELETE'});dialog.close();await load();refresh();});});}
function historySection(type,id){return `<section class="record-history-section"><div class="record-section-heading"><h2>Historique des interactions</h2><span class="tag">Partagé avec l’équipe</span></div><div class="gmail-history-state">${icon('mail')}<div><strong>Échanges Gmail non connectés</strong><p>Les messages et leur contenu apparaîtront ici après l’intégration Gmail. Seules les actions enregistrées dans Ciblix sont affichées aujourd’hui.</p></div></div><div id="record-history" data-history-key="${type}/${id}" aria-live="polite"><p class="empty">Chargement de l’historique…</p></div></section>`;}
async function loadRecordHistory(type,id,offset=0){const host=document.querySelector('#record-history');if(!host||host.dataset.historyKey!==type+'/'+id)return;try{const data=await api('/'+type+'/'+id+'/history?limit=25&offset='+offset);if(!host.isConnected||host.dataset.historyKey!==type+'/'+id)return;host.innerHTML=data.items.map(a=>`<article class="record-timeline-item"><span class="avatar mini">${esc(initials(a.actor_name))}</span><div><strong>${esc(a.summary)}</strong><p>${esc(a.actor_name)} · <time datetime="${esc(a.created_at)}">${esc(localDate(a.created_at))}</time></p></div></article>`).join('')||'<p class="empty">Aucune interaction enregistrée pour cette fiche.</p>';if(data.total>25){host.insertAdjacentHTML('beforeend',`<nav class="history-pagination" aria-label="Pagination de l’historique"><button id="history-newer" ${offset===0?'disabled':''}>Plus récentes</button><span>${offset+1}–${Math.min(offset+25,data.total)} sur ${data.total}</span><button id="history-older" ${offset+25>=data.total?'disabled':''}>Plus anciennes</button></nav>`);host.querySelector('#history-newer').onclick=()=>loadRecordHistory(type,id,Math.max(0,offset-25));host.querySelector('#history-older').onclick=()=>loadRecordHistory(type,id,offset+25);}}catch(e){if(!host.isConnected)return;host.innerHTML=errorText(e.message)+'<button class="text-link" id="retry-history">Réessayer</button>';host.querySelector('#retry-history').onclick=()=>loadRecordHistory(type,id,offset);}}
function contactDrawer(id){const c=contactBy(id);if(!c)return;const image=store.images.find(i=>i.contact_id===id),company=companyBy(c.company_id),next=followupsFor(c,'contacts'),status=tracking(c,'contacts');modal(c.name,`<div class="contact-record-meta"><span class="tracking-badge tracking-${status.key}">${status.label}</span><span>${esc(c.job_title||'Fonction non renseignée')}</span></div>${company?`<a class="contact-company-link" href="/app/entreprises/${company.id}">${icon('building')} ${esc(company.name)} ${icon('arrow')}</a>`:'<p class="record-subtle">Contact sans entreprise</p>'}<div class="record-owner-line">${icon('people')} Responsable : <strong>${esc(memberName(c.owner_user_id))}</strong></div><section class="record-coordinates"><h3>Coordonnées</h3>${addressFor(id).map(e=>`<p>${icon('mail')} <a href="mailto:${esc(e)}">${esc(e)}</a></p>`).join('')||'<p>E-mail non renseigné</p>'}<p>${icon('phone')} ${c.phone?`<a href="tel:${esc(c.phone.replace(/\s/g,''))}">${esc(c.phone)}</a>`:'Téléphone non renseigné'}</p></section>${recordActions(c,'contacts')}<section class="record-next-section"><div class="record-section-heading"><h2>Prochaine relance</h2><button class="text-link" id="contact-followup">＋ Planifier</button></div>${next.length?next.slice(0,3).map(r=>`<button class="record-next-action" data-followup-actions="${r.id}"><span>${icon('clock')}</span><span><strong>${esc(r.subject)}</strong><small>${esc(localDate(r.due_at))} · ${esc(memberName(r.owner_user_id))}</small></span>${icon('arrow')}</button>`).join(''):'<p class="record-subtle">Aucune relance prévue pour ce contact.</p>'}</section><section class="record-notes-section"><h3 class="detail-subheading">Notes partagées</h3>${notesHTML('contacts',id)}</section>${historySection('contacts',id)}<details class="record-card-details"><summary>Carte de visite</summary>${image?`<div class="business-card-preview"><img src="/api/v1/images/${image.id}" alt="Carte de visite du contact"></div>`:'<p class="record-subtle">Aucune carte jointe.</p>'}<label class="card-photo-button">${icon('phone')} Joindre une carte<input id="contact-card-upload" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"></label></details>`,true);bindEntityActions(c,'contacts');bindNotes('contacts',id,()=>contactDrawer(id));bindRecords();document.querySelector('#contact-followup').onclick=()=>followupForm(null,id);document.querySelector('#contact-card-upload').onchange=safeAction(async()=>{const file=document.querySelector('#contact-card-upload').files[0];if(!file)return;await uploadCard(id,file);await load();contactDrawer(id);toast('Carte de visite enregistrée.');});loadRecordHistory('contacts',id);}
function companyPage(id){const c=companyBy(id);if(!c){shell('<div class="panel empty"><h1>Entreprise introuvable</h1><a class="text-link" href="/app/contacts?vue=entreprises">Revenir au répertoire</a></div>');return;}document.title=c.name+' — Ciblix';const people=store.contacts.filter(p=>p.company_id===id),next=followupsFor(c,'companies'),status=tracking(c,'companies');shell(`<a class="text-link company-back" href="/app/contacts?vue=entreprises">← Toutes les entreprises</a><div class="record-company-header"><span class="company-avatar">${esc(initials(c.name))}</span><div><span class="eyebrow">${esc(c.sector||'SECTEUR NON RENSEIGNÉ')}${c.city?' · '+esc(c.city):''}</span><h1>${esc(c.name)}</h1><p>${esc(memberName(c.owner_user_id))} · Responsable du suivi</p></div><span class="tracking-badge tracking-${status.key}">${status.label}</span></div><div class="company-detail-grid directory-detail-grid"><section><div class="panel record-main-panel">${historySection('companies',id)}</div><section class="panel record-main-panel"><div class="record-section-heading"><h2>Notes partagées</h2></div>${notesHTML('companies',id)}</section></section><aside><section class="panel company-context"><div class="record-section-heading"><h2>Prochaine relance</h2></div>${next.slice(0,3).map(r=>`<button class="record-next-action" data-followup-actions="${r.id}"><span>${icon('clock')}</span><span><strong>${esc(r.subject)}</strong><small>${esc(localDate(r.due_at))} · ${esc(memberName(r.owner_user_id))}</small></span>${icon('arrow')}</button>`).join('')||'<p>Aucune relance prévue.</p>'}<button class="button small" id="company-followup">＋ Planifier une relance</button><small class="unverified-note">État des réponses non vérifié · Gmail non connecté.</small></section><section class="panel company-context"><div class="record-section-heading"><h2>Contacts et coordonnées <span class="number-tag">${people.length}</span></h2></div>${people.map(p=>`<div class="company-person-coordinates"><button class="linked-person" data-open-contact="${p.id}"><span class="avatar">${esc(initials(p.name))}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.job_title||'Contact')}${p.archived_at?' · Archivé':''}</small></span>${icon('arrow')}</button>${addressFor(p.id).map(e=>`<a href="mailto:${esc(e)}">${icon('mail')} ${esc(e)}</a>`).join('')}${p.phone?`<a href="tel:${esc(p.phone.replace(/\s/g,''))}">${icon('phone')} ${esc(p.phone)}</a>`:''}</div>`).join('')||'<p>Aucun contact lié.</p>'}<button class="text-link" id="company-add-contact">Ajouter un contact ${icon('arrow')}</button></section><section class="panel company-context"><h2>À propos et gestion</h2><p>${esc(c.description||'Ajoutez une description pour partager le contexte avec votre équipe.')}</p><p>${esc(c.sector||'Secteur non renseigné')}${c.city?' · '+esc(c.city):''}</p>${recordActions(c,'companies')}</section></aside></div>`);bindRecords();bindEntityActions(c,'companies');bindNotes('companies',id,()=>companyPage(id));document.querySelector('#company-followup').onclick=()=>followupForm(null,people.find(p=>!p.archived_at)?.id,id);document.querySelector('#company-add-contact').onclick=()=>{entityForm('contacts');document.querySelector('#entity-form select[name="company_id"]').value=id;};loadRecordHistory('companies',id);}

function followupForm(id=null,contactId=null,companyId=null){const r=id?store.followups.find(r=>r.id===id):{};const selected=r.contact_id||contactId;const localInput=v=>{if(!v)return new Intl.DateTimeFormat('sv-SE',{timeZone:'Africa/Tunis',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date()).replace(' ','T');return new Intl.DateTimeFormat('sv-SE',{timeZone:'Africa/Tunis',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v)).replace(' ','T');};modal(id?'Modifier la relance':'Planifier une relance',`<form id="followup-form" class="prototype-form">${id?'':`<label>Contact<select name="contact_id"><option value="">Sans contact</option>${store.contacts.filter(c=>!c.archived_at).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.name)} · ${esc(companyBy(c.company_id)?.name||'Sans entreprise')}</option>`).join('')}</select></label><label>Entreprise (si aucun contact)<select name="company_id"><option value="">Sans entreprise</option>${store.companies.filter(c=>!c.archived_at).map(c=>`<option value="${c.id}" ${c.id===companyId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`}<label>Prochaine action<input name="subject" maxlength="300" value="${esc(r.subject)}" required></label><label>Échéance · heure de Tunis<input type="datetime-local" name="local_due" value="${localInput(r.due_at)}" required></label><label>Responsable<select name="owner_user_id">${ownerOptions(r.owner_user_id||session.user.id)}</select></label><button class="button" type="submit">Enregistrer la relance</button></form>`);bindForm('followup-form',async d=>{d.due_at=new Date(d.local_due+':00+01:00').toISOString();delete d.local_due;if(!id){if(d.contact_id){d.company_id=contactBy(d.contact_id)?.company_id||null;}else d.contact_id=null;d.company_id=d.company_id||null;}await api('/followups'+(id?'/'+id:''),{method:id?'PATCH':'POST',body:d});dialog.close();await sync();toast('Relance enregistrée.');});}
function followupActions(id){const r=store.followups.find(r=>r.id===id);modal('La prochaine étape',`<p>${esc(r.subject)}</p><p>${esc(localDate(r.due_at))} · ${esc(memberName(r.owner_user_id))}</p><div class="board-dialog-actions"><button class="button" id="finish-followup">${icon('check')} Marquer comme terminé</button><button class="button board-secondary" id="edit-followup">${icon('clock')} Modifier ou reporter</button><button class="text-link" id="cancel-followup">Annuler la relance</button>${isAdmin()?'<button class="text-link" id="delete-followup">Supprimer définitivement</button>':''}</div>`);document.querySelector('#finish-followup').onclick=safeAction(async()=>{await api('/followups/'+id,{method:'PATCH',body:{status:'completed'}});dialog.close();await sync();toast('Relance terminée.');});document.querySelector('#edit-followup').onclick=()=>followupForm(id);document.querySelector('#cancel-followup').onclick=()=>{modal('Annuler la relance',`<form class="prototype-form" id="cancel-followup-form"><label>Raison (facultative)<input name="cancellation_reason" maxlength="300"></label><button class="button" type="submit">Confirmer l’annulation</button></form>`);bindForm('cancel-followup-form',async d=>{await api('/followups/'+id,{method:'PATCH',body:{...d,status:'cancelled'}});dialog.close();await sync();});};document.querySelector('#delete-followup')?.addEventListener('click',()=>{modal('Supprimer cette relance ?',`<p>Cette suppression est définitive.</p><button class="button" id="confirm-followup-delete">Confirmer la suppression</button>`);document.querySelector('#confirm-followup-delete').onclick=safeAction(async()=>{await api('/followups/'+id,{method:'DELETE'});dialog.close();await sync();});});}
function draftForm(id){const r=store.followups.find(f=>f.id===id),person=contactBy(r.contact_id);modal('Préparer votre relance',`<p>${esc(person?.name||companyBy(r.company_id)?.name||r.subject)}</p><span class="tag">Brouillon local · Gmail non connecté</span><form class="prototype-form" id="draft-form"><label>Votre message<textarea name="local_draft" required maxlength="10000" rows="8">${esc(r.local_draft||`Bonjour${person?' '+person.name.split(' ')[0]:''},\n\nJe me permets de revenir vers vous concernant notre précédent échange. Seriez-vous disponible pour faire le point ?\n\nBien cordialement,\n${session.user.name}`)}</textarea></label><button class="button" type="submit">Enregistrer le brouillon local</button><p>Le texte est conservé dans Ciblix. Aucun brouillon Gmail ni envoi n’est effectué.</p></form>`);bindForm('draft-form',async d=>{await api('/followups/'+id,{method:'PATCH',body:d});dialog.close();await sync();toast('Brouillon local enregistré. Aucun envoi.');});}
function bindRecords(){document.querySelectorAll('[data-open-contact]').forEach(b=>b.onclick=()=>{if(b.dataset.openContact)contactDrawer(b.dataset.openContact);});document.querySelectorAll('[data-followup-actions]').forEach(b=>b.onclick=()=>followupActions(b.dataset.followupActions));document.querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>draftForm(b.dataset.draft));}
function agendaLive(){document.title='Relances — Ciblix';const states=['Tous','Mon suivi','Terminées','Annulées'];const list=store.followups.filter(r=>reminderScope==='Terminées'?r.status==='completed':reminderScope==='Annulées'?r.status==='cancelled':r.status==='pending'&&(reminderScope!=='Mon suivi'||r.owner_user_id===session.user.id)).sort((a,b)=>new Date(a.due_at)-new Date(b.due_at));const groups=reminderScope==='Terminées'||reminderScope==='Annulées'?[[reminderScope,list]]:[['En retard',list.filter(r=>dayKey(r.due_at)<today())],['Aujourd’hui',list.filter(r=>dayKey(r.due_at)===today())],['À venir',list.filter(r=>dayKey(r.due_at)>today())]];shell(greeting('Relances','Une prochaine action claire pour chaque relation.','Planifier une relance')+`<div class="collection-toolbar"><div class="tabs" role="group" aria-label="Filtrer les relances">${states.map(s=>`<button data-reminder-scope="${s}" class="${s===reminderScope?'active':''}">${s}</button>`).join('')}</div><span class="tag">Échéances en heure de Tunis</span></div><div class="agenda-layout"><div>${groups.map(([name,items])=>`<section class="panel agenda-day"><div class="panel-heading"><h2>${name}</h2><span class="number-tag">${items.length}</span></div>${items.length?items.map(r=>`<div class="agenda-live-date">${esc(localDate(r.due_at))} · ${esc(memberName(r.owner_user_id))}</div>${reminderRow(r)}`).join(''):'<p class="empty">Aucune relance dans cette catégorie.</p>'}</section>`).join('')}</div><aside class="focus-card"><span class="focus-icon">${icon('clock')}</span><span class="eyebrow">LE SUIVI EN ÉQUIPE</span><h2>Une prochaine étape.<br>Un esprit plus libre.</h2><p>Les relances et les brouillons locaux sont partagés dans votre organisation. L’état des réponses reste non vérifié tant que Gmail n’est pas connecté.</p></aside></div>`);document.querySelector('#page-add').onclick=()=>followupForm();document.querySelectorAll('[data-reminder-scope]').forEach(b=>b.onclick=()=>{reminderScope=b.dataset.reminderScope;agendaLive();});bindRecords();}
async function membersModal(){const invites=isAdmin()?await api('/invitations'):[];modal('Membres et accès',`<p>Les collaborateurs partagent toutes les fiches de ${esc(session.organization.name)}.</p>${session.members.map(m=>`<div class="linked-person"><span class="avatar">${esc(initials(m.name))}</span><span><strong>${esc(m.name)}</strong><small>${esc(m.email)} · ${m.active?(m.role==='admin'?'Administrateur':'Collaborateur'):'Accès désactivé'}</small></span>${isAdmin()?`<button class="text-link" data-manage-member="${m.id}">Gérer</button>`:''}</div>`).join('')}${isAdmin()?`<h3 class="detail-subheading">Inviter un collaborateur</h3><form id="invite-form" class="prototype-form"><label>Adresse Google<input name="email" type="email" required></label><label>Rôle<select name="role"><option value="member">Collaborateur</option><option value="admin">Administrateur</option></select></label><button class="button" type="submit">Envoyer l’invitation</button><p>Un e-mail personnel sera envoyé avec un lien sécurisé valable sept jours.</p></form><div id="invite-link" aria-live="polite"></div><h3 class="detail-subheading">Invitations</h3>${invites.map(i=>`<div class="linked-person"><span><strong>${esc(i.email)}</strong><small>${i.accepted_at?'Acceptée':i.revoked_at?'Révoquée':new Date(i.expires_at)<new Date()?'Expirée':'Expire le '+esc(localDate(i.expires_at))}</small></span>${!i.accepted_at&&!i.revoked_at?`<button class="text-link" data-revoke-invite="${i.id}">Révoquer</button>`:''}</div>`).join('')}`:'<p>La gestion des invitations et des rôles est réservée aux administrateurs.</p>'}`);if(!isAdmin())return;bindForm('invite-form',async d=>{const invite=await api('/invitations',{method:'POST',body:d});document.querySelector('#invite-link').innerHTML=`<div class="auth-success" role="status"><strong>Invitation envoyée</strong><p>${esc(invite.email)} recevra un lien sécurisé valable sept jours.</p></div>`;});document.querySelectorAll('[data-revoke-invite]').forEach(b=>b.onclick=safeAction(async()=>{await api('/invitations/'+b.dataset.revokeInvite,{method:'DELETE'});await membersModal();}));document.querySelectorAll('[data-manage-member]').forEach(b=>b.onclick=()=>{const m=session.members.find(m=>m.id===b.dataset.manageMember);modal('Accès de '+m.name,`<form class="prototype-form" id="member-form"><label>Rôle<select name="role"><option value="member" ${m.role==='member'?'selected':''}>Collaborateur</option><option value="admin" ${m.role==='admin'?'selected':''}>Administrateur</option></select></label><label>État<select name="active"><option value="true" ${m.active?'selected':''}>Actif</option><option value="false" ${!m.active?'selected':''}>Désactivé</option></select></label><p>Une organisation doit conserver au moins un administrateur actif.</p><button class="button" type="submit">Enregistrer les accès</button></form>`);bindForm('member-form',async d=>{await api('/members/'+m.id,{method:'PATCH',body:{...d,active:d.active==='true'}});dialog.close();await sync();});});}
function switchOrg(){modal('Votre espace de travail',`<p>Chaque organisation dispose de ses propres contacts, entreprises et collaborateurs.</p><form class="prototype-form" id="switch-form"><label>Organisation<select name="organization_id">${session.organizations.map(o=>`<option value="${o.id}" ${o.id===session.organization.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label><button class="button" type="submit">Ouvrir cet espace</button></form>`);bindForm('switch-form',async d=>{await api('/organizations/switch',{method:'POST',body:d});dialog.close();await load();go('/app');});}
function exportContacts(){const quote=v=>{let s=String(v||'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const rows=[['Nom','Entreprise','E-mails','Téléphone'],...store.contacts.filter(c=>!c.archived_at).map(c=>[c.name,companyBy(c.company_id)?.name,addressFor(c.id).join(', '),c.phone])];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ciblix-contacts.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function connectionLive(){renderAuthPage();}
function render(){const aliases={'/dashboard':'/app','/contacts':'/app/contacts','/entreprises':'/app/contacts?vue=entreprises','/relances':'/app/relances','/emails':'/app'};if(aliases[location.pathname])history.replaceState({},'',aliases[location.pathname]);const path=location.pathname;if(path==='/'){homepage();return;}if(authPages.has(path)){renderAuthPage();return;}if(!session){connectionLive();return;}if(path==='/app')dashboardLive();else if(path==='/app/contacts')directory();else if(path==='/app/relances')agendaLive();else if(/^\/app\/entreprises\/[^/]+$/.test(path))companyPage(decodeURIComponent(path.split('/').pop()));else shell('<div class="panel empty"><h1>Page introuvable</h1><a href="/app">Revenir au tableau de bord</a></div>');}
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.defaultPrevented||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||e.button!==0)return;const u=new URL(a.href,location.href);if(u.origin!==location.origin||u.hash||u.pathname.startsWith('/auth/')||u.pathname.startsWith('/api/'))return;e.preventDefault();if(!session&&u.pathname.startsWith('/app')){location.href='/connexion';return;}go(u.pathname+u.search);});
window.addEventListener('popstate',render);dialog.addEventListener('close',()=>dialog.classList.remove('contact-drawer'));
async function initialize(){if(location.pathname==='/'||authPages.has(location.pathname)){render();return;}app.innerHTML='<main class="board-empty" aria-live="polite"><h1>Ciblix</h1><p>Chargement de votre espace…</p></main>';try{await load();render();}catch(e){if(location.pathname!=='/connexion')app.innerHTML=`<main class="board-empty"><h1>Votre espace est indisponible</h1>${errorText(e.message)}<button class="button" id="retry-load">Réessayer</button></main>`;document.querySelector('#retry-load')?.addEventListener('click',initialize);}}
initialize();
